  2340      bstarts = (int32_t*)(_src + BLOSC_MIN_HEADER_LENGTH);
  2341    }
  2342
  2343    // Some checks for malformed buffers
  2344    if (blocksize <= 0 || blocksize > nbytes || typesize <= 0 || typesize > BLOSC_MAX_TYPESIZE) {
  2345      return -1;
  2346    }
  2347
  2348    /* Check region boundaries */
  2349    if ((start < 0) || (start * typesize > nbytes)) {
  2350      BLOSC_TRACE_ERROR("`start` out of bounds.");
  2351      return -1;
  2352    }
  2353
  2354    if ((stop < 0) || (stop * typesize > nbytes)) {
  2355      BLOSC_TRACE_ERROR("`start`+`nitems` out of bounds.");
  2356      return -1;
  2357    }
  2358
  2359    if (_src + srcsize < (uint8_t *)(bstarts + nblocks)) {
  2360      /* Not enough input to read all `bstarts` */
  2361      return -1;
  2362    }
  2363
  2364    for (j = 0; j < nblocks; j++) {
  2365      bsize = blocksize;
  2366      leftoverblock = 0;
  2367      if ((j == nblocks - 1) && (leftover > 0)) {
  2368        bsize = leftover;
  2369        leftoverblock = 1;
  2370      }
  2371
  2372      /* Compute start & stop for each block */
  2373      startb = start * typesize - j * blocksize;
  2374      stopb = stop * typesize - j * blocksize;
  2375      if (stopb <= 0) {
  2376        // We can exit as soon as this block is beyond stop
  2377        break;
  2378      }
  2379      if (startb >= blocksize) {
  2380        continue;
  2381      }
  2382      if (startb < 0) {
  2383        startb = 0;
  2384      }
  2385      if (stopb > blocksize) {
  2386        stopb = blocksize;
  2387      }
  2388      bsize2 = stopb - startb;
  2389
  2390      /* Do the actual data copy */
  2391      struct thread_context* scontext = context->serial_context;
  2392
  2393      /* Resize the temporaries in serial context if needed */
  2394      if (blocksize != scontext->tmp_blocksize) {
  2395        my_free(scontext->tmp);
  2396        scontext->tmp_nbytes = (size_t)3 * context->blocksize + ebsize;
  2397        scontext->tmp = my_malloc(scontext->tmp_nbytes);
  2398        scontext->tmp2 = scontext->tmp + blocksize;
  2399        scontext->tmp3 = scontext->tmp + blocksize + ebsize;
  2400        scontext->tmp4 = scontext->tmp + 2 * blocksize + ebsize;
  2401        scontext->tmp_blocksize = (int32_t)blocksize;
  2402      }
  2403
  2404      // Regular decompression.  Put results in tmp2.
  2405      // If the block is aligned and the worst case fits in destination, let's avoid a copy
  2406      bool get_single_block = ((startb == 0) && (bsize == nitems * typesize));
  2407      uint8_t* tmp2 = get_single_block ? dest : scontext->tmp2;
  2408      // If memcpyed we don't have a bstarts section (because it is not needed)
  2409      int32_t src_offset = memcpyed ? header_overhead + j * bsize : sw32_(bstarts + j);
  2410      cbytes = blosc_d(context->serial_context, bsize, leftoverblock,
  2411                       src, srcsize, src_offset, j,
  2412                       tmp2, 0, scontext->tmp, scontext->tmp3);
  2413      if (cbytes < 0) {
  2414        ntbytes = cbytes;
  2415        break;
  2416      }
  2417      if (!get_single_block) {
  2418        /* Copy to destination */
  2419        memcpy((uint8_t *) dest + ntbytes, tmp2 + startb, (unsigned int) bsize2);
  2420      }
  2421      cbytes = (int)bsize2;
  2422      ntbytes += cbytes;
  2423    }
  2424
  2425    return ntbytes;
  2426  }
