  2943  int blosc_cbuffer_validate(const void* cbuffer, size_t cbytes, size_t* nbytes) {
  2944    size_t header_cbytes, header_blocksize;
  2945    if (cbytes < BLOSC_MIN_HEADER_LENGTH) {
  2946      /* Compressed data should contain enough space for header */
  2947      *nbytes = 0;
  2948      return -1;
