  2950    blosc_cbuffer_sizes(cbuffer, nbytes, &header_cbytes, &header_blocksize);
  2951    if (header_cbytes != cbytes) {
  2952      /* Compressed size from header does not match `cbytes` */
  2953      *nbytes = 0;
  2954      return -1;
  2955    }
  2956    if (*nbytes > BLOSC_MAX_BUFFERSIZE) {
  2957      /* Uncompressed size is larger than allowed */
  2958      return -1;
  2959    }
  2960    return 0;
  2961  }
