   570  int do_nothing(int8_t filter, char cmode) {
   571    if (cmode == 'c') {
   572      return (filter == BLOSC_NOFILTER);
   573    } else {
   574      // TRUNC_PREC do not have to be applied during decompression
   575      return ((filter == BLOSC_NOFILTER) || (filter == BLOSC_TRUNC_PREC));
   576    }
   577  }
