   590  int last_filter(const uint8_t* filters, char cmode) {
   591    int last_index = -1;
   592    for (int i = BLOSC2_MAX_FILTERS - 1; i >= 0; i--) {
   593      if (!do_nothing(filters[i], cmode))  {
   594        last_index = i;
   595      }
   596    }
   597    return last_index;
   598  }
