   682  // Optimized version for detecting runs.  It compares 8 bytes values wherever possible.
   683  static bool get_run(const uint8_t* ip, const uint8_t* ip_bound) {
   684    uint8_t x = *ip;
   685    int64_t value, value2;
   686    /* Broadcast the value for every byte in a 64-bit register */
   687    memset(&value, x, 8);
   688    while (ip < (ip_bound - 8)) {
   689  #if defined(BLOSC_STRICT_ALIGN)
   690      memcpy(&value2, ip, 8);
   691  #else
   692      value2 = *(int64_t*)ip;
   693  #endif
   694      if (value != value2) {
   695        // Values differ.  We don't have a run.
   696        return false;
   697      }
   698      else {
   699        ip += 8;
   700      }
   701    }
   702    /* Look into the remainder */
   703    while ((ip < ip_bound) && (*ip == x)) ip++;
   704    return ip == ip_bound ? true : false;
   705  }
