  2196  /* The public secure routine for decompression with context. */
  2197  int blosc2_decompress_ctx(blosc2_context* context, const void* src, int32_t srcsize,
  2198                            void* dest, int32_t destsize) {
  2199    int result;
  2200
  2201    if (context->do_compress != 0) {
  2202      BLOSC_TRACE_ERROR("Context is not meant for decompression.  Giving up.");
  2203      return -10;
  2204    }
  2205
  2206    result = blosc_run_decompression_with_context(context, src, srcsize, dest, destsize);
  2207
  2208    // Reset a possible block_maskout
  2209    if (context->block_maskout != NULL) {
  2210      free(context->block_maskout);
  2211      context->block_maskout = NULL;
  2212    }
  2213    context->block_maskout_nitems = 0;
  2214
  2215    return result;
  2216  }
