  2219  /* The public secure routine for decompression. */
  2220  int blosc2_decompress(const void* src, int32_t srcsize, void* dest, int32_t destsize) {
  2221    int result;
  2222    char* envvar;
  2223    long nthreads;
  2224    blosc2_context *dctx;
  2225    blosc2_dparams dparams = BLOSC2_DPARAMS_DEFAULTS;
  2226
  2227    /* Check whether the library should be initialized */
  2228    if (!g_initlib) blosc_init();
  2229
  2230    /* Check for a BLOSC_NTHREADS environment variable */
  2231    envvar = getenv("BLOSC_NTHREADS");
  2232    if (envvar != NULL) {
  2233      nthreads = strtol(envvar, NULL, 10);
  2234      if ((nthreads != EINVAL) && (nthreads > 0)) {
  2235        result = blosc_set_nthreads((int)nthreads);
  2236        if (result < 0) { return result; }
  2237      }
  2238    }
  2239
  2240    /* Check for a BLOSC_NOLOCK environment variable.  It is important
  2241       that this should be the last env var so that it can take the
  2242       previous ones into account */
  2243    envvar = getenv("BLOSC_NOLOCK");
  2244    if (envvar != NULL) {
  2245      dparams.nthreads = g_nthreads;
  2246      dctx = blosc2_create_dctx(dparams);
  2247      result = blosc2_decompress_ctx(dctx, src, srcsize, dest, destsize);
  2248      blosc2_free_ctx(dctx);
  2249      return result;
  2250    }
  2251
  2252    pthread_mutex_lock(&global_comp_mutex);
  2253
  2254    result = blosc_run_decompression_with_context(
  2255            g_global_context, src, srcsize, dest, destsize);
  2256
  2257    pthread_mutex_unlock(&global_comp_mutex);
  2258
  2259    return result;
  2260  }
  2440    }
  2441
  2442    /* Minimally populate the context */
  2443    memset(&context, 0, sizeof(blosc2_context));
  2444    context.src = src;
  2445    context.dest = dest;
  2446    context.typesize = (uint8_t)_src[BLOSC2_CHUNK_TYPESIZE];
  2447    context.blocksize = sw32_(_src + BLOSC2_CHUNK_BLOCKSIZE);
  2448    context.header_flags = *(_src + 2);
  2449    context.filter_flags = get_filter_flags(context.header_flags, context.typesize);
  2450    context.schunk = g_schunk;
  2451    context.nthreads = 1;  // force a serial decompression; fixes #95
  2452    context.serial_context = create_thread_context(&context, 0);
  2453    if ((context.header_flags & BLOSC_DOSHUFFLE) &&
  2454        (context.header_flags & BLOSC_DOBITSHUFFLE)) {
  2455      // Support for lazy chunks exists only for Blosc2, and needs the context.
  2456      context.blosc2_flags = _src[BLOSC2_CHUNK_BLOSC2_FLAGS];
  2457      if (context.blosc2_flags & 0x08) {
  2458        BLOSC_TRACE_ERROR("blosc_getitem does not support lazy chunks.  Use blosc2_getitem_ctx instead.");
  2459        return -2;
  2460      }
  2461    }
  2462
  2463    /* Call the actual getitem function */
  2464    result = _blosc_getitem(&context, src, INT32_MAX, start, nitems, dest);
  2465
  2466    /* Release resources */
  2467    free_thread_context(context.serial_context);
  2468    return result;
  2469  }
