  2471  int blosc2_getitem_ctx(blosc2_context* context, const void* src, int32_t srcsize,
  2472      int start, int nitems, void* dest) {
  2473    uint8_t* _src = (uint8_t*)(src);
  2474    int result;
  2475
  2476    /* Minimally populate the context */
  2477    context->typesize = _src[BLOSC2_CHUNK_TYPESIZE];
  2478    context->blocksize = sw32_(_src + BLOSC2_CHUNK_BLOCKSIZE);
  2479    context->header_flags = *(_src + 2);
  2480    context->filter_flags = get_filter_flags(*(_src + 2), context->typesize);
  2481    if (context->serial_context == NULL) {
  2482      context->serial_context = create_thread_context(context, 0);
  2483    }
  2484
  2485    /* Call the actual getitem function */
  2486    result = _blosc_getitem(context, src, srcsize, start, nitems, dest);
  2487
  2488    return result;
  2489  }
