  2491  /* execute single compression/decompression job for a single thread_context */
  2492  static void t_blosc_do_job(void *ctxt)
  2493  {
  2494    struct thread_context* thcontext = (struct thread_context*)ctxt;
  2495    blosc2_context* context = thcontext->parent_context;
  2496    int32_t cbytes;
  2497    int32_t ntdest;
  2498    int32_t tblocks;               /* number of blocks per thread */
  2499    int32_t tblock;                /* limit block on a thread */
  2500    int32_t nblock_;              /* private copy of nblock */
  2501    int32_t bsize;
  2502    int32_t leftoverblock;
  2503    /* Parameters for threads */
  2504    int32_t blocksize;
  2505    int32_t ebsize;
  2506    int32_t srcsize;
  2507    bool compress = context->do_compress != 0;
  2508    int32_t maxbytes;
  2509    int32_t nblocks;
  2510    int32_t leftover;
  2511    int32_t leftover2;
  2512    int32_t* bstarts;
  2513    const uint8_t* src;
  2514    uint8_t* dest;
  2515    uint8_t* tmp;
  2516    uint8_t* tmp2;
  2517    uint8_t* tmp3;
  2518
  2519    /* Get parameters for this thread before entering the main loop */
  2520    blocksize = context->blocksize;
  2521    ebsize = blocksize + context->typesize * sizeof(int32_t);
  2522    maxbytes = context->destsize;
  2523    nblocks = context->nblocks;
  2524    leftover = context->leftover;
  2525    bstarts = context->bstarts;
  2525    bstarts = context->bstarts;
  2526    src = context->src;
  2527    srcsize = context->srcsize;
  2528    dest = context->dest;
  2529
  2530    /* Resize the temporaries if needed */
  2531    if (blocksize != thcontext->tmp_blocksize) {
  2532      my_free(thcontext->tmp);
  2533      thcontext->tmp_nbytes = (size_t)3 * context->blocksize + ebsize;
  2534      thcontext->tmp = my_malloc(thcontext->tmp_nbytes);
  2535      thcontext->tmp2 = thcontext->tmp + blocksize;
  2536      thcontext->tmp3 = thcontext->tmp + blocksize + ebsize;
  2537      thcontext->tmp4 = thcontext->tmp + 2 * blocksize + ebsize;
  2538      thcontext->tmp_blocksize = blocksize;
  2539    }
  2540
  2541    tmp = thcontext->tmp;
  2542    tmp2 = thcontext->tmp2;
  2543    tmp3 = thcontext->tmp3;
  2544
  2545    // Determine whether we can do a static distribution of workload among different threads
  2546    bool memcpyed = context->header_flags & (uint8_t)BLOSC_MEMCPYED;
  2547    bool static_schedule = (!compress || memcpyed) && context->block_maskout == NULL;
  2548    if (static_schedule) {
  2549        /* Blocks per thread */
  2550        tblocks = nblocks / context->nthreads;
  2551        leftover2 = nblocks % context->nthreads;
  2552        tblocks = (leftover2 > 0) ? tblocks + 1 : tblocks;
  2553        nblock_ = thcontext->tid * tblocks;
  2554        tblock = nblock_ + tblocks;
  2555        if (tblock > nblocks) {
  2556            tblock = nblocks;
  2557        }
  2558    }
  2559    else {
  2560      // Use dynamic schedule via a queue.  Get the next block.
  2561      pthread_mutex_lock(&context->count_mutex);
  2562      context->thread_nblock++;
  2563      nblock_ = context->thread_nblock;
  2564      pthread_mutex_unlock(&context->count_mutex);
  2565      tblock = nblocks;
  2566    }
  2567
  2568    /* Loop over blocks */
  2569    leftoverblock = 0;
  2570    while ((nblock_ < tblock) && (context->thread_giveup_code > 0)) {
  2571      bsize = blocksize;
  2572      if (nblock_ == (nblocks - 1) && (leftover > 0)) {
  2573        bsize = leftover;
  2574        leftoverblock = 1;
  2575      }
  2576      if (compress) {
  2577        if (memcpyed) {
  2578          if (!context->prefilter) {
  2579            /* We want to memcpy only */
  2580            memcpy(dest + BLOSC_MAX_OVERHEAD + nblock_ * blocksize,
  2581                   src + nblock_ * blocksize, (unsigned int) bsize);
  2582            cbytes = (int32_t) bsize;
  2583          }
  2584          else {
  2585            /* Only the prefilter has to be executed, and this is done in blosc_c().
  2586             * However, no further actions are needed, so we can put the result
  2587             * directly in dest. */
  2588            cbytes = blosc_c(thcontext, bsize, leftoverblock, 0,
  2589                             ebsize, src, nblock_ * blocksize,
  2590                             dest + BLOSC_MAX_OVERHEAD + nblock_ * blocksize,
  2591                             tmp, tmp3);
  2592          }
  2593        }
  2594        else {
  2595          /* Regular compression */
  2596          cbytes = blosc_c(thcontext, bsize, leftoverblock, 0,
  2597                            ebsize, src, nblock_ * blocksize, tmp2, tmp, tmp3);
  2598        }
  2599      }
  2600      else {
  2601        /* Regular decompression */
  2602        if (srcsize < (int32_t)(BLOSC_MAX_OVERHEAD + (sizeof(int32_t) * nblocks))) {
  2603          /* Not enough input to read all `bstarts` */
  2604          cbytes = -1;
  2605        }
  2606        else {
  2607          // If memcpyed we don't have a bstarts section (because it is not needed)
  2608          int32_t src_offset = memcpyed ? BLOSC_MAX_OVERHEAD + nblock_ * blocksize : sw32_(bstarts + nblock_);
  2609          cbytes = blosc_d(thcontext, bsize, leftoverblock,
  2610                            src, srcsize, src_offset, nblock_,
  2611                            dest, nblock_ * blocksize, tmp, tmp2);
  2612        }
  2613      }
  2614
  2615      /* Check whether current thread has to giveup */
  2616      if (context->thread_giveup_code <= 0) {
  2617        break;
  2618      }
  2619
  2620      /* Check results for the compressed/decompressed block */
  2621      if (cbytes < 0) {            /* compr/decompr failure */
  2622        /* Set giveup_code error */
  2623        pthread_mutex_lock(&context->count_mutex);
  2624        context->thread_giveup_code = cbytes;
  2625        pthread_mutex_unlock(&context->count_mutex);
  2626        break;
  2627      }
  2628
  2629      if (compress && !memcpyed) {
  2630        /* Start critical section */
  2631        pthread_mutex_lock(&context->count_mutex);
  2632        ntdest = context->output_bytes;
  2633        // Note: do not use a typical local dict_training variable here
  2634        // because it is probably cached from previous calls if the number of
  2635        // threads does not change (the usual thing).
  2636        if (!(context->use_dict && context->dict_cdict == NULL)) {
  2637          _sw32(bstarts + nblock_, (int32_t) ntdest);
  2638        }
  2639
  2640        if ((cbytes == 0) || (ntdest + cbytes > maxbytes)) {
  2641          context->thread_giveup_code = 0;  /* uncompressible buf */
  2642          pthread_mutex_unlock(&context->count_mutex);
  2643          break;
  2644        }
  2645        context->thread_nblock++;
  2646        nblock_ = context->thread_nblock;
  2647        context->output_bytes += cbytes;
  2648        pthread_mutex_unlock(&context->count_mutex);
  2649        /* End of critical section */
  2650
  2651        /* Copy the compressed buffer to destination */
  2652        memcpy(dest + ntdest, tmp2, (unsigned int) cbytes);
  2653      }
  2654      else if (static_schedule) {
  2655        nblock_++;
  2656      }
  2657      else {
  2658        pthread_mutex_lock(&context->count_mutex);
  2659        context->thread_nblock++;
  2660        nblock_ = context->thread_nblock;
  2661        context->output_bytes += cbytes;
  2662        pthread_mutex_unlock(&context->count_mutex);
  2663      }
  2664
  2665    } /* closes while (nblock_) */
  2666
  2667    if (static_schedule) {
  2668      context->output_bytes = context->sourcesize;
  2669      if (compress) {
  2670        context->output_bytes += BLOSC_MAX_OVERHEAD;
  2671      }
  2672    }
  2673
  2674  }
