  1199  /* Serial version for compression/decompression */
  1200  static int serial_blosc(struct thread_context* thread_context) {
  1201    blosc2_context* context = thread_context->parent_context;
  1202    int32_t j, bsize, leftoverblock;
  1203    int32_t cbytes;
  1204    int32_t ntbytes = (int32_t)context->output_bytes;
  1205    int32_t* bstarts = context->bstarts;
  1206    uint8_t* tmp = thread_context->tmp;
  1207    uint8_t* tmp2 = thread_context->tmp2;
  1208    int dict_training = context->use_dict && (context->dict_cdict == NULL);
  1209    bool memcpyed = context->header_flags & (uint8_t)BLOSC_MEMCPYED;
  1210
  1211    for (j = 0; j < context->nblocks; j++) {
  1212      if (context->do_compress && !memcpyed && !dict_training) {
  1213        _sw32(bstarts + j, ntbytes);
  1214      }
  1215      bsize = context->blocksize;
  1216      leftoverblock = 0;
  1217      if ((j == context->nblocks - 1) && (context->leftover > 0)) {
  1218        bsize = context->leftover;
  1219        leftoverblock = 1;
  1220      }
  1550    }
  1551    if (header_flags & BLOSC_DOBITSHUFFLE) {
  1552      flags |= BLOSC_DOBITSHUFFLE;
  1553    }
  1554    if (header_flags & BLOSC_DODELTA) {
  1555      flags |= BLOSC_DODELTA;
  1556    }
  1557    if (header_flags & BLOSC_MEMCPYED) {
  1558      flags |= BLOSC_MEMCPYED;
  1559    }
  1560    return flags;
  1561  }
