  2015  /* The public secure routine for compression. */
  2016  int blosc2_compress(int clevel, int doshuffle, int32_t typesize,
  2017                      const void* src, int32_t srcsize, void* dest, int32_t destsize) {
  2018    int error;
  2019    int result;
  2020    char* envvar;
  2021
  2022    /* Check whether the library should be initialized */
  2023    if (!g_initlib) blosc_init();
  2024
  2025    /* Check for a BLOSC_CLEVEL environment variable */
  2026    envvar = getenv("BLOSC_CLEVEL");
  2027    if (envvar != NULL) {
  2028      long value;
  2029      value = strtol(envvar, NULL, 10);
  2030      if ((value != EINVAL) && (value >= 0)) {
  2031        clevel = (int)value;
  2032      }
  2033    }
  2034
  2035    /* Check for a BLOSC_SHUFFLE environment variable */
  2036    envvar = getenv("BLOSC_SHUFFLE");
  2037    if (envvar != NULL) {
  2038      if (strcmp(envvar, "NOSHUFFLE") == 0) {
  2039        doshuffle = BLOSC_NOSHUFFLE;
  2040      }
  2041      if (strcmp(envvar, "SHUFFLE") == 0) {
  2042        doshuffle = BLOSC_SHUFFLE;
  2043      }
  2044      if (strcmp(envvar, "BITSHUFFLE") == 0) {
  2045        doshuffle = BLOSC_BITSHUFFLE;
  2046      }
  2047    }
  2048
  2049    /* Check for a BLOSC_DELTA environment variable */
  2050    envvar = getenv("BLOSC_DELTA");
  2051    if (envvar != NULL) {
  2052      if (strcmp(envvar, "1") == 0) {
  2053        blosc_set_delta(1);
  2054      } else {
  2055        blosc_set_delta(0);
  2056      }
  2057    }
  2058
  2059    /* Check for a BLOSC_TYPESIZE environment variable */
  2060    envvar = getenv("BLOSC_TYPESIZE");
  2061    if (envvar != NULL) {
  2062      long value;
  2063      value = strtol(envvar, NULL, 10);
  2064      if ((value != EINVAL) && (value > 0)) {
  2065        typesize = (size_t)value;
  2066      }
  2067    }
  2068
  2069    /* Check for a BLOSC_COMPRESSOR environment variable */
  2070    envvar = getenv("BLOSC_COMPRESSOR");
  2071    if (envvar != NULL) {
  2072      result = blosc_set_compressor(envvar);
  2073      if (result < 0) { return result; }
  2074    }
  2075
  2076    /* Check for a BLOSC_COMPRESSOR environment variable */
  2077    envvar = getenv("BLOSC_BLOCKSIZE");
  2078    if (envvar != NULL) {
  2079      long blocksize;
  2080      blocksize = strtol(envvar, NULL, 10);
  2081      if ((blocksize != EINVAL) && (blocksize > 0)) {
  2082        blosc_set_blocksize((size_t)blocksize);
  2083      }
  2084    }
  2085
  2086    /* Check for a BLOSC_NTHREADS environment variable */
  2087    envvar = getenv("BLOSC_NTHREADS");
  2088    if (envvar != NULL) {
  2089      long nthreads;
  2090      nthreads = strtol(envvar, NULL, 10);
  2091      if ((nthreads != EINVAL) && (nthreads > 0)) {
  2092        result = blosc_set_nthreads((int)nthreads);
  2093        if (result < 0) { return result; }
  2094      }
  2095    }
  2096
  2097    /* Check for a BLOSC_NOLOCK environment variable.  It is important
  2098       that this should be the last env var so that it can take the
  2099       previous ones into account */
  2100    envvar = getenv("BLOSC_NOLOCK");
  2101    if (envvar != NULL) {
  2102      // TODO: here is the only place that returns an extended header from
  2103      //   a blosc_compress() call.  This should probably be fixed.
  2104      const char *compname;
  2105      blosc2_context *cctx;
  2106      blosc2_cparams cparams = BLOSC2_CPARAMS_DEFAULTS;
  2107
  2108      blosc_compcode_to_compname(g_compressor, &compname);
  2109      /* Create a context for compression */
  2110      build_filters(doshuffle, g_delta, typesize, cparams.filters);
  2111      // TODO: cparams can be shared in a multithreaded environment.  do a copy!
  2112      cparams.typesize = (uint8_t)typesize;
  2113      cparams.compcode = (uint8_t)g_compressor;
  2114      cparams.clevel = (uint8_t)clevel;
  2115      cparams.nthreads = (uint8_t)g_nthreads;
  2116      cctx = blosc2_create_cctx(cparams);
  2117      /* Do the actual compression */
  2118      result = blosc2_compress_ctx(cctx, src, srcsize, dest, destsize);
  2119      /* Release context resources */
  2120      blosc2_free_ctx(cctx);
  2121      return result;
  2122    }
  2123
  2124    pthread_mutex_lock(&global_comp_mutex);
  2125
  2126    /* Initialize a context compression */
  2127    uint8_t* filters = calloc(1, BLOSC2_MAX_FILTERS);
  2128    uint8_t* filters_meta = calloc(1, BLOSC2_MAX_FILTERS);
  2129    build_filters(doshuffle, g_delta, typesize, filters);
  2130    error = initialize_context_compression(
  2131      g_global_context, src, srcsize, dest, destsize, clevel, filters,
  2132      filters_meta, (int32_t)typesize, g_compressor, g_force_blocksize, g_nthreads, g_nthreads,
  2133      g_schunk);
  2134    free(filters);
  2135    free(filters_meta);
  2136    if (error <= 0) {
  2137      pthread_mutex_unlock(&global_comp_mutex);
  2138      return error;
  2139    }
  2140
  2141    /* Write chunk header without extended header (Blosc1 compatibility mode) */
  2142    error = write_compression_header(g_global_context, false);
  2143    if (error < 0) {
  2144      pthread_mutex_unlock(&global_comp_mutex);
  2145      return error;
  2146    }
  2147
  2148    result = blosc_compress_context(g_global_context);
  2149
  2150    pthread_mutex_unlock(&global_comp_mutex);
  2151
  2152    return result;
  2153  }
