  2156  /* The public routine for compression. */
  2157  int blosc_compress(int clevel, int doshuffle, size_t typesize, size_t nbytes,
  2158                     const void* src, void* dest, size_t destsize) {
  2159    return blosc2_compress(clevel, doshuffle, (int32_t)typesize, src, (int32_t)nbytes, dest, (int32_t)destsize);
  2160  }
