  2162
  2163  int blosc_run_decompression_with_context(blosc2_context* context, const void* src, int32_t srcsize,
  2164                                           void* dest, int32_t destsize) {
  2165    int32_t ntbytes;
  2166    uint8_t* _src = (uint8_t*)src;
  2167    uint8_t version;
  2168    int error;
  2169
  2170    if (srcsize <= 0) {
  2171      /* Invalid argument */
  2172      return -1;
  2173    }
  2174    version = _src[BLOSC2_CHUNK_VERSION];                        /* blosc format version */
  2175    if (version > BLOSC_VERSION_FORMAT) {
  2176      /* Version from future */
  2177      return -1;
  2178    }
  2179
  2180    error = initialize_context_decompression(context, src, srcsize, dest, destsize);
  2181    if (error < 0) {
  2182      return error;
  2183    }
  2184
  2185    /* Do the actual decompression */
  2186    ntbytes = do_job(context);
  2187    if (ntbytes < 0) {
  2188      return -1;
  2189    }
  2190
  2191    assert(ntbytes <= (int32_t)destsize);
  2192    return ntbytes;
  2193  }
